    let bytes_gnss = hex!("8d3461cf9908388930080f948ea1");
    let (_, msg_gnss) = Message::from_bytes((&bytes_gnss, 0)).unwrap();

    if let ExtendedSquitterADSB(adsb_msg) = msg_gnss.df {
