    // I048/170: Track Status (0x00: confirmed, combined, no doubtful/manoeuvre, maintaining)
    let ts = record.track_status.as_ref().unwrap();
    assert!(ts.confirmed);
    assert_eq!(ts.sensor_type, SensorType::Combined);
    assert!(!ts.doubtful);
    assert!(!ts.manoeuvring);
